long backoffMs = 200;      // from the backoff formula
long retryAfterMs = 2000;  // from the Retry-After header
long waitMs = Math.max(backoffMs, retryAfterMs);
System.out.println(waitMs);

long deadline = 500;        // ms the caller will wait
long attemptTimeout = 100;  // each attempt gives up after this
long[] waits = {100, 200, 400};
long elapsed = 0;
int attempts = 0;
for (int i = 0; ; i++) {
    attempts++;
    elapsed += attemptTimeout;   // every attempt times out
    if (i == waits.length) break;   // no retries left
    if (elapsed + waits[i] + attemptTimeout > deadline) break;   // the next try would miss the deadline
    elapsed += waits[i];
}
System.out.println(attempts + " attempts, gave up at " + elapsed + " ms");

int requests = 100;           // the dependency is down: every call fails
int maxRetriesPerCall = 2;
int budget = requests / 10;   // retries may be at most 10% of requests
int retries = 0;
for (int r = 0; r < requests; r++) {
    for (int k = 0; k < maxRetriesPerCall && retries < budget; k++) {
        retries++;
    }
}
System.out.println("calls sent: " + (requests + retries));

int layers = 5;
