int[] responses = {503, 503, 200};   // the server's answer on attempts 1, 2, 3
long[] backoff = {100, 200};         // capped exponential backoff (jitter left out for clarity)
long retryAfterMs = 300;             // Retry-After sent with each 503
long waited = 0;
int attempt = 0;
while (true) {
    int status = responses[attempt];
    attempt++;
    if (status == 200) {
        System.out.println("ok after " + attempt + " attempts, waited " + waited + " ms");
        break;
    }
    boolean retryable = status == 503 || status == 429;
    if (!retryable || attempt == responses.length) {
        System.out.println("fail " + status);
        break;
    }
    waited += Math.max(backoff[attempt - 1], retryAfterMs);
}

